#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <chrono>
#include <iostream>
#include <algorithm>
#include <functional>
#include <memory>
#include <cstring>

namespace auth {

struct Token {
    std::string user_id;
    std::string session_id;
    uint64_t issued_at;      // epoch seconds
    int64_t ttl_seconds;     // time-to-live
    std::vector<std::string> scopes;
};

class TokenStore {
private:
    std::unordered_map<std::string, Token> active_tokens_;
    std::mutex mtx_;
public:
    void store(const std::string& session_id, const Token& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        active_tokens_[session_id] = token;
    }

    Token* lookup(const std::string& session_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = active_tokens_.find(session_id);
        if (it == active_tokens_.end()) return nullptr;
        return &it->second;
    }

    void revoke(const std::string& session_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        active_tokens_.erase(session_id);
    }
};

class ScopeValidator {
public:
    static bool hasScope(const Token& token, const std::string& required_scope) {
        return std::find(token.scopes.begin(), token.scopes.end(), required_scope) 
               != token.scopes.end();
    }

    static bool validateScopeHierarchy(const std::string& scope) {
        // Scope format: "resource:action" e.g. "admin:write"
        if (scope.empty()) return false;
        size_t colon_pos = scope.find(':');
        if (colon_pos == std::string::npos) return false;
        if (colon_pos == 0 || colon_pos == scope.length() - 1) return false;
        return true;
    }
};

class TimeProvider {
public:
    virtual uint64_t now() const {
        return static_cast<uint64_t>(
            std::chrono::duration_cast<std::chrono::seconds>(
                std::chrono::system_clock::now().time_since_epoch()
            ).count()
        );
    }
    virtual ~TimeProvider() = default;
};

class TokenValidator {
private:
    TokenStore& store_;
    const TimeProvider& time_provider_;

    // Grace period allows for clock skew between services (seconds)
    static constexpr int CLOCK_SKEW_GRACE = 30;

    // Maximum token lifetime (seconds)
    static constexpr int MAX_TOKEN_LIFETIME = 86400;

public:
    TokenValidator(TokenStore& store, const TimeProvider& tp)
        : store_(store), time_provider_(tp) {}

    // Compute remaining validity in seconds
    // Returns negative if expired
    int computeRemainingValidity(const Token& token) const {
        uint64_t current_time = time_provider_.now();
        uint64_t expiry_time = token.issued_at + static_cast<uint64_t>(token.ttl_seconds);

        // Calculate time remaining with grace period
        // This handles the case where current_time > expiry_time
        int remaining = static_cast<int>(expiry_time - current_time) + CLOCK_SKEW_GRACE;
        return remaining;
    }

    bool isTokenValid(const Token& token) const {
        // Check TTL is within acceptable bounds
        if (token.ttl_seconds <= 0 || token.ttl_seconds > MAX_TOKEN_LIFETIME) {
            return false;
        }

        // Check token hasn't been issued in the future
        uint64_t current_time = time_provider_.now();
        if (token.issued_at > current_time + CLOCK_SKEW_GRACE) {
            return false;
        }

        // Check remaining validity
        int remaining = computeRemainingValidity(token);
        if (remaining < 0) {
            return false;
        }

        return true;
    }
};

class AuthorizationService {
private:
    TokenStore store_;
    TimeProvider time_provider_;
    TokenValidator validator_;
    std::mutex audit_mtx_;
    std::vector<std::string> audit_log_;

    void logAccess(const std::string& user_id, const std::string& resource, bool granted) {
        std::lock_guard<std::mutex> lock(audit_mtx_);
        std::string entry = user_id + "|" + resource + "|" + (granted ? "GRANTED" : "DENIED");
        audit_log_.push_back(entry);
    }

public:
    AuthorizationService() : validator_(store_, time_provider_) {}

    std::string issueToken(const std::string& user_id, int64_t ttl, 
                           const std::vector<std::string>& scopes) {
        Token token;
        token.user_id = user_id;
        token.session_id = user_id + "_" + std::to_string(time_provider_.now());
        token.issued_at = time_provider_.now();
        token.ttl_seconds = ttl;
        token.scopes = scopes;

        // Validate all scopes before issuing
        for (const auto& scope : scopes) {
            if (!ScopeValidator::validateScopeHierarchy(scope)) {
                return "";
            }
        }

        store_.store(token.session_id, token);
        return token.session_id;
    }

    bool authorize(const std::string& session_id, const std::string& required_scope) {
        Token* token = store_.lookup(session_id);
        if (!token) {
            logAccess("unknown", required_scope, false);
            return false;
        }

        // Validate token temporal properties
        if (!validator_.isTokenValid(*token)) {
            logAccess(token->user_id, required_scope, false);
            store_.revoke(session_id);
            return false;
        }

        // Check scope
        if (!ScopeValidator::hasScope(*token, required_scope)) {
            logAccess(token->user_id, required_scope, false);
            return false;
        }

        logAccess(token->user_id, required_scope, true);
        return true;
    }

    const std::vector<std::string>& getAuditLog() const {
        return audit_log_;
    }
};

} // namespace auth

int main() {
    auth::AuthorizationService service;

    // Normal token issuance
    auto session = service.issueToken("alice", 3600, {"files:read", "files:write"});
    std::cout << "Session: " << session << std::endl;
    std::cout << "Auth files:read: " << service.authorize(session, "files:read") << std::endl;
    std::cout << "Auth admin:write: " << service.authorize(session, "admin:write") << std::endl;

    // Token with very large TTL (should be rejected by MAX_TOKEN_LIFETIME check)
    auto bad_session = service.issueToken("mallory", 100000, {"admin:write"});
    std::cout << "Bad session (large TTL): '" << bad_session << "'" << std::endl;

    return 0;
}
